def digest(data):
    return hashlib.sha256(data).hexdigest()

def read_whole(path,record):
    data=Path(path).read_bytes()
    if len(data)!=record['bytes'] or digest(data)!=record['sha256']:
        raise ValueError('The whole parameter object differs: '+str(path))
    return data

def chunks(text):
    inside=False
    escaped=False
    current=[]
    result=[]
    for char in text:
        if inside:
            current.append(char)
            if escaped:
                escaped=False
            elif char=='\\':
                escaped=True
            elif char=='"':
                inside=False
        elif char=='"':
            inside=True
            current.append(char)
        elif char not in ' \r\t\n':
            current.append(char)
            if char in '{}[],':
                result.append(''.join(current))
                current=[]
    if inside or escaped:
        raise ValueError('The full JSON text has an incomplete string')
    if current:
        result.append(''.join(current))
    return result

def transform(values,hunks,reverse=False):
    result=list(values)
    for hunk in reversed(hunks):
        at=hunk['new_line' if reverse else 'old_line']
        before=hunk['new' if reverse else 'old']
        after=hunk['old' if reverse else 'new']
        if result[at:at+len(before)]!=before:
            raise ValueError('A complete anchored parameter segment changed')
        result[at:at+len(before)]=after
    return result

def significant(argv):
    changes={'--outdir','--current-radial-factor','--independent-envelope-branch',
        '--pending-parallel-envelope-run','--pending-parallel-envelope-source',
        '--material-envelope-parent-report','--material-envelope-seed-checkpoint',
        '--material-envelope-seed-report'}
    result=[]
    index=0
    while index<len(argv):
        flag=argv[index]
        if flag in changes:
            index+=1 if flag=='--independent-envelope-branch' else 2
        else:
            result.append(flag)
            index+=1
    return result

def validate_parameters(original,current,mode,shared):
    if current.get('complete_source_sha256_record')!=SHARED or current.get('complete_source_sha256_field')!='complete_source_sha256':
        raise ValueError('The full shared source metadata record changed')
    if shared.get('full_runtime_source_role_count')!=131 or current.get('full_runtime_source_role_count')!=131:
        raise ValueError('Retain every actual current source role')
    sources=shared['complete_source_sha256']
    if any(sources.get(key)!=value for key,value in original['complete_source_sha256'].items()):
        raise ValueError('An original complete source identity was omitted')
    if any(sources.get(record['name'])!=record['sha256'] for record in CURRENT):
        raise ValueError('A complete J1845 runtime source identity changed')
    if len(original['steps'])!=2 or len(current['steps'])!=2:
        raise ValueError('Retain the complete science and pure pair')
    old,new=original['steps'],current['steps']
    if significant(old[0]['args'])!=significant(new[0]['args']):
        raise ValueError('A numerical parameter, fixed input, budget or threshold changed')
    argv=new[0]['args']
    if argv[argv.index('--angles')+1]!='2048' or argv[argv.index('--current-radial-factor')+1]!='2':
        raise ValueError('Retain full N2048 and request the complete radial bisection')
    for before,after in zip(old,new):
        a=next(iter(before['summary'].values()))
        b=next(iter(after['summary'].values()))
        if any(b.get(key)!=value for key,value in a.items()):
            raise ValueError('An original scalar selector was omitted or rewritten')
    if next(iter(old[0]['progress_summary'].values()))!=next(iter(new[0]['progress_summary'].values())):
        raise ValueError('Retain every original progress selector')
    if current['actual_parent_report_sha256'] is not None or current['actual_parent_checkpoint_sha256'] is not None:
        raise ValueError('Do not invent future actual parent identities')
    if mode=='independent':
        if '--independent-envelope-branch' not in argv or '--material-envelope-parent-report' in argv:
            raise ValueError('An independent reference-point branch cannot pretend to read a parent')
    elif '--independent-envelope-branch' in argv or '--material-envelope-parent-report' not in argv:
        raise ValueError('A terminal/final branch must read its actual complete parent report')
    if ('--material-envelope-seed-checkpoint' in argv)!=(mode=='final'):
        raise ValueError('Only final mode copies old complete free-variable words')
    if mode=='final' and argv[argv.index('--material-envelope-seed-checkpoint')+1]!='{work}/fixed-fejer-immutable-point-first/final.npz':
        raise ValueError('Use the actual original complete final save filename')

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo',type=Path,required=True)
    p.add_argument('--output-dir',type=Path,required=True)
    p.add_argument('--verify-existing',action='store_true')
    args=p.parse_args()
    repo=args.repo.resolve()
    out=args.output_dir.resolve()
    if out==repo or repo in out.parents:
        raise ValueError('Reconstruct in scratch, without writing repository sources, refs or queues')
    if not args.verify_existing:
        out.mkdir(parents=True,exist_ok=True)
    shared=json.loads(read_whole(repo/SHARED['path'],SHARED))
    records=[]
    for item in SPEC:
        original=read_whole(repo/item['parent']['path'],item['parent'])
        before=chunks(original.decode('utf-8'))
        if (''.join(before)+'\n').encode('utf-8')!=original:
            raise ValueError('The exact original compact JSON serialization changed')
        after=transform(before,item['hunks'])
        data=(''.join(after)+'\n').encode('utf-8')
        back=(''.join(transform(after,item['hunks'],reverse=True))+'\n').encode('utf-8')
        if back!=original:
            raise ValueError('Complete inverse original parameter bytes differ')
        record=item['output']
        if len(data)!=record['bytes'] or digest(data)!=record['sha256']:
            raise ValueError('The complete resulting plan bytes differ: '+record['name'])
        validate_parameters(json.loads(original),json.loads(data),record['mode'],shared)
        destination=out/record['name']
        if args.verify_existing or destination.exists():
            read_whole(destination,record)
        else:
            destination.write_bytes(data)
            read_whole(destination,record)
        records.append(dict(mode=record['mode'],name=record['name'],bytes=record['bytes'],
            sha256=record['sha256'],complete_forward_and_reverse_bytes_checked=True))
    print(json.dumps(dict(schema='complete-fixed-fejer-J1845-parameter-reproduction-v1',
        source_sha256=digest(Path(__file__).read_bytes()),complete_plans=records,
        generated_sources_imported=False,scientific_execution_performed=False,
        actual_parent_or_scientific_result_generated=False,refs_or_queues_modified=False),
        sort_keys=True,allow_nan=False))

if __name__=='__main__':
    main()
